-- Fiche Mes goûts (CP) - anglais, notion 'en_gouts'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cp', 'english', 'Mes goûts', $fiche$
[titre]J'aime, je n'aime pas[/titre]
[cadre]j'aime = [b]I like[/b] · je n'aime pas = [b]I don't like[/b]
Ma couleur préférée est… = [b]My favourite colour is[/b]…[/cadre]
[cadre=astuce]I like black (pas de « le » en anglais devant la couleur).[/cadre]
